DAY = 9

L0 = [
  {'part': 'read'},
  "The URL shortener is small enough to finish in one interview and rich enough to show every skill: estimation, a key generation problem, a read-heavy path to cache, and a few product decisions with real consequences. Here are the parts candidates usually rush.",
  {'h': 'Generating codes without collisions'},
  "The cleanest approach is a unique 64-bit number turned into base62. A counter shared by all servers is a bottleneck, so each app server **leases a range** (for example 1,000,000 numbers at a time) from a database row with an atomic `UPDATE ... RETURNING`, then hands them out locally. If a server dies, the unused part of its range is skipped: harmless. To stop people guessing other links by incrementing a code, run the number through a reversible scramble (a multiplication modulo a prime, or a small block cipher) before encoding.",
  {'h': 'The redirect path, measured'},
  {'table': {'head': ['Step', 'Typical time', 'Notes'], 'rows': [['CDN or edge cache hit', '5 to 20 ms', 'Only if the redirect is cacheable (careful with analytics)'], ['App server + Redis hit', '1 to 3 ms server time', 'Most popular codes stay hot'], ['Redis miss, key-value DB read', '5 to 10 ms', 'Then fill the cache'], ['Return 301 or 302', '-', '302 if you need to count every click']]}},
  {'h': 'Product decisions with system consequences'},
  {'ul': ['**Analytics:** recording each click synchronously slows redirects; publish a click event to a queue and aggregate asynchronously.', '**Abuse:** short links hide malicious destinations; check new URLs against a malware/phishing list and allow takedowns.', '**Expiry and deletion:** a background job, or a TTL in the store; decide whether expired codes can ever be reused (usually never).', '**Permanence:** links end up printed in books and papers. Shutting a shortener down breaks them forever.']},
  {'part': 'real'},
  {'case': {'who': 'Google', 'when': '2018 to 2025', 'title': 'Turning off goo.gl',
    'body': ["Google stopped accepting new goo.gl short links in 2018 and later announced that existing links would stop working on August 25, 2025, noting that more than 99% of them had had no activity in the previous month. After feedback that the links were embedded in countless documents, videos and posts, Google adjusted the plan in 2025 to keep actively used links working and deactivate only those that had shown no activity in late 2024."],
    'lesson': 'A URL shortener makes a promise that outlives its product strategy. Design for permanence: cheap storage per link, and a plan for what happens if the service ever closes.',
    'src': [['Google URL Shortener links will no longer be available (Google Developers Blog)', 'https://developers.googleblog.com/en/google-url-shortener-links-will-no-longer-be-available/']]}},
  {'part': 'apply'},
  {'code': "// Range-leased IDs -> scrambled -> base62 codes\nconst ALPHABET = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';\nconst toBase62 = n => { let s = ''; do { s = ALPHABET[Number(n % 62n)] + s; n /= 62n; } while (n > 0n); return s; };\n\n// Reversible scramble on the 7-char space (62^7): multiply, rotate digits, multiply again.\n// Each step is a bijection, so codes stay unique; consecutive IDs no longer look consecutive.\nconst M = 62n ** 7n, A = 2654435761n, B = 40503n, LOW = 62n ** 3n, HIGH = 62n ** 4n;\nconst rotate = x => (x % HIGH) * LOW + x / HIGH;      // move the 4 low digits to the top\nconst scramble = n => (rotate((n * A) % M) * B) % M;\n\nlet next = 1000000n, end = 2000000n;   // leased range: UPDATE ranges SET next = next + 1e6 RETURNING ...\nfunction newCode() {\n  if (next >= end) throw new Error('lease a new range');\n  return toBase62(scramble(next++)).padStart(7, '0');\n}\nconsole.log([newCode(), newCode(), newCode()]);   // consecutive IDs, unguessable-looking codes\nconsole.log('capacity', (62 ** 7).toLocaleString(), 'codes');", 'lang': 'js', 'cap': 'Unique, short and not sequential-looking'},
  {'code': "// Redirect handler: cache first, 302 so every click is seen, click event off the hot path\napp.get('/:code', async (req, res) => {\n  const code = req.params.code;\n  let url = await redis.get(`l:${code}`);\n  if (!url) {\n    const row = await kv.get(code);                 // key-value store or SQL by primary key\n    if (!row || (row.expires_at && row.expires_at < Date.now())) return res.status(404).send('Not found');\n    url = row.long_url;\n    await redis.set(`l:${code}`, url, { EX: 86400 });\n  }\n  queue.publish('clicks', { code, at: Date.now(), ref: req.get('referer') || null }); // fire and forget\n  res.redirect(302, url);\n});", 'lang': 'js', 'cap': 'The read path that carries 99% of traffic'},
  {'check': ['Estimate writes, reads and storage for 5 years before choosing storage.', 'Generate codes from leased ID ranges or Snowflake IDs, scrambled and base62-encoded.', 'Cache hot codes; decide 301 vs 302 based on whether you must count every click.', 'Send click analytics through a queue, never inline.', 'Check destinations against malware/phishing lists and support takedowns.', 'Never reuse codes, and decide how links survive if the service changes.']},
]

L1 = [
  {'part': 'read'},
  "File storage systems look like 'upload a file, download a file', but the interesting design is in how bytes move and how changes are detected. The rule from the lesson (metadata in a database, bytes in object storage) is the foundation; chunking, hashing and a change journal are what make sync efficient.",
  {'h': 'Sync, walked through'},
  {'ol': ['A user edits a 200 MB video project file; the client splits it into 4 MB chunks and hashes each.', 'The client asks the server which of those 50 chunk hashes it lacks. Only 2 chunks changed, so only 8 MB is uploaded.', 'Chunks go directly to object storage with pre-signed URLs; the server never proxies bytes.', 'The client commits a new file version: an ordered list of chunk hashes. This is a small metadata write, done in a transaction.', 'The commit appends an entry to the user’s change journal with a new cursor value.', 'Other devices hold a long-poll or push connection; they are told "something changed", fetch journal entries after their cursor, and download only missing chunks.']},
  {'h': 'Conflicts and versions'},
  "Two devices editing the same file offline both commit against the same base version. The server accepts the first and detects the second (its base version is stale); instead of overwriting, it saves the second as a 'conflicted copy' next to the original. Keeping old versions is cheap because unchanged chunks are shared between versions.",
  {'part': 'real'},
  {'case': {'who': 'Dropbox', 'when': '2016', 'title': 'Magic Pocket: moving exabytes out of the public cloud',
    'body': ["Dropbox moved most of its file content from Amazon S3 to Magic Pocket, its own block storage system, while keeping metadata in its own databases. Files are split into blocks addressed by hash; Magic Pocket stores those immutable blocks with erasure coding across zones for durability at lower cost than full replication. At Dropbox's scale, owning the storage layer changed their economics."],
    'lesson': 'Content-addressed, immutable blocks make storage, dedup and replication simpler. Separating metadata from bytes lets each be optimised on its own.',
    'src': [['Inside the Magic Pocket (Dropbox)', 'https://dropbox.tech/infrastructure/inside-the-magic-pocket']]}},
  {'case': {'who': 'Dropbox', 'when': '2020', 'title': 'Rewriting the sync engine',
    'body': ["Dropbox described rewriting the client sync engine (the part that reconciles local files, the server and in-flight changes) from scratch, as Nucleus, in Rust. The old engine's data model made it hard to reason about correctness. The new one was built around a clear model of three trees (remote, local and synced state), with heavy use of randomised testing to find rare sync bugs before users did."],
    'lesson': 'Sync is a distributed systems problem on every device. A clear state model and aggressive testing matter more than raw speed.',
    'src': [['Rewriting the heart of our sync engine (Dropbox)', 'https://dropbox.tech/infrastructure/rewriting-the-heart-of-our-sync-engine']]}},
  {'part': 'apply'},
  {'code': "// Which chunks changed? Hash fixed-size chunks and diff the lists\nconst crypto = require('crypto');\nconst CHUNK = 4 * 1024 * 1024;\nfunction chunkHashes(buf) {\n  const out = [];\n  for (let i = 0; i < buf.length; i += CHUNK) out.push(crypto.createHash('sha256').update(buf.subarray(i, i + CHUNK)).digest('hex'));\n  return out;\n}\nasync function sync(fileBuf, fileId) {\n  const hashes = chunkHashes(fileBuf);\n  const { missing } = await api.post('/v1/blocks/check', { hashes });            // server returns hashes it lacks\n  for (const h of missing) {\n    const i = hashes.indexOf(h);\n    const { uploadUrl } = await api.post('/v1/blocks/upload-url', { hash: h });\n    await fetch(uploadUrl, { method: 'PUT', body: fileBuf.subarray(i * CHUNK, (i + 1) * CHUNK) });\n  }\n  return api.post(`/v1/files/${fileId}/commit`, { hashes, baseVersion: localVersion(fileId) }); // 409 = conflict\n}", 'lang': 'js', 'cap': 'Chunked, deduplicated upload'},
  {'code': "CREATE TABLE blocks (hash char(64) PRIMARY KEY, size int NOT NULL, stored_at timestamptz DEFAULT now());\nCREATE TABLE file_versions (\n  file_id bigint, version int, block_hashes text[] NOT NULL, created_by bigint, created_at timestamptz DEFAULT now(),\n  PRIMARY KEY (file_id, version));\nCREATE TABLE journal (user_id bigint, cursor bigserial, file_id bigint, version int, PRIMARY KEY (user_id, cursor));\n-- devices ask: SELECT * FROM journal WHERE user_id = $1 AND cursor > $2 ORDER BY cursor", 'lang': 'sql', 'cap': 'Metadata for versions, dedup and change tracking'},
  {'check': ['Store bytes in object storage and only metadata in the database.', 'Upload directly from clients with pre-signed URLs; use multipart uploads for large files.', 'Chunk and hash files so only changed chunks move.', 'Commit versions with a base version and handle conflicts explicitly.', 'Give each user a change journal with cursors for efficient sync.', 'Keep old versions for a retention period; shared chunks make this cheap.']},
]

L2 = [
  {'part': 'read'},
  "Building a key-value store is the best way to see how the distributed systems ideas from Days 5 to 8 combine. Each mechanism solves one specific problem, and each has a cost the next mechanism has to deal with.",
  {'h': 'Following one write'},
  {'ol': ['The client sends `put(cart:42, {...})` to any node; that node becomes the coordinator.', 'It hashes the key onto the ring and finds the N = 3 replicas (skipping virtual nodes that belong to the same physical machine or zone).', 'It sends the write to all three and waits for W = 2 acknowledgements, then answers the client.', 'One replica is down: the write goes to the next healthy node with a "hint" saying who it is really for (hinted handoff); when the owner returns, the hint is delivered.', 'Each replica appends the write to its commit log and memtable (an LSM engine), with a version (vector clock or timestamp).', 'Later, a background anti-entropy process compares replicas using Merkle trees and repairs any differences.']},
  {'h': 'Following one read'},
  "The coordinator asks R = 2 replicas. If their versions match, it answers. If one is older, it returns the newest and quietly writes the newest value back to the stale replica (read repair). If versions are concurrent (vector clocks show neither came first), it returns both to the client or merges them by the data type's rule.",
  {'part': 'real'},
  {'case': {'who': 'Amazon', 'when': '2007', 'title': 'Dynamo: the blueprint',
    'body': ["The Dynamo paper combined consistent hashing, replication with sloppy quorums, hinted handoff, vector clocks, Merkle-tree anti-entropy and gossip-based membership into one highly available store for services like the shopping cart. It became the template for Cassandra, Riak and Voldemort."],
    'lesson': 'Each technique in Dynamo addresses one failure mode; together they trade strict consistency for being always writable.',
    'src': [['Dynamo: Amazon’s Highly Available Key-value Store', 'https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf']]}},
  {'case': {'who': 'Amazon', 'when': '2022', 'title': 'DynamoDB: what changed in fifteen years',
    'body': ["The 2022 DynamoDB paper explains how the managed service differs from the original Dynamo: it uses Multi-Paxos-based replication with a leader per partition for strongly consistent writes, focuses on predictable latency at any scale rather than maximum availability, and spends much of its design on admission control, partition splitting for hot keys, and operational automation."],
    'lesson': 'For a managed service, predictable performance and operability became more important than the leaderless design of the original paper.',
    'src': [['Amazon DynamoDB: A Scalable, Predictably Performant, and Fully Managed NoSQL Database Service (USENIX ATC 2022)', 'https://www.usenix.org/conference/atc22/presentation/elhemali']]}},
  {'part': 'apply'},
  {'code': "// Merkle-tree style comparison: find which key ranges differ between two replicas without sending all data\nconst crypto = require('crypto');\nconst h = s => crypto.createHash('sha1').update(s).digest('hex').slice(0, 8);\nfunction rangeHashes(store, buckets = 8) {\n  const parts = Array.from({ length: buckets }, () => []);\n  for (const [k, v] of Object.entries(store).sort()) parts[parseInt(h(k), 16) % buckets].push(k + '=' + v);\n  return parts.map(p => h(p.join('|')));\n}\nconst a = { 'cart:1': 'x', 'cart:2': 'y', 'cart:3': 'z', 'user:9': 'ana' };\nconst b = { ...a, 'cart:2': 'y2' };                     // replica b has a newer value for one key\nconst ha = rangeHashes(a), hb = rangeHashes(b);\nconsole.log('ranges to sync:', ha.map((x, i) => (x !== hb[i] ? i : null)).filter(i => i !== null)); // just one bucket", 'lang': 'js', 'cap': 'Compare summaries first, exchange data only where they differ'},
  {'check': ['State the consistency model up front (tunable quorums, last-writer-wins or vector clocks).', 'Place replicas in different zones, skipping virtual nodes on the same machine.', 'Handle temporary failures with hinted handoff and permanent drift with anti-entropy.', 'Detect failures with gossip and heartbeats, not a single monitor.', 'Choose an LSM engine for write-heavy workloads and plan compaction.', 'Monitor hot partitions and be able to split them.']},
]

L3 = [
  {'part': 'read'},
  "A crawler's difficulty is not downloading pages; it is deciding what to download next, never hammering one site, and not wasting effort on duplicates and traps, while the web changes constantly.",
  {'h': 'The URL frontier in detail'},
  "The frontier has two layers. **Front queues** order URLs by priority (importance and expected change rate). **Back queues** are one per host, each with a 'next allowed fetch time' from that host's politeness delay (robots.txt crawl-delay or a default like one request per second). A worker picks the back queue whose next allowed time has passed, fetches one URL, and schedules the host's next slot. This guarantees politeness without global locks.",
  {'h': 'Duplicates, traps and freshness'},
  {'ul': ['**URL normalisation** before dedup: lowercase host, remove default ports, sort query parameters, drop fragments and tracking parameters.', '**Seen-URL test:** a Bloom filter over billions of URLs, with occasional false positives accepted (a missed page) in exchange for memory.', '**Content dedup:** hash page content (or a SimHash for near-duplicates) so mirrors are stored once.', '**Traps:** calendars and session IDs create infinite URLs; cap depth per site, URL length and pages per host.', '**Recrawl:** pages that changed on the last visits get revisited sooner; static pages later. Use `If-Modified-Since` and ETags to make revisits cheap.']},
  {'part': 'real'},
  {'case': {'who': 'Google (Brin and Page)', 'when': '1998', 'title': 'The original Google crawler',
    'body': ["The paper introducing Google described a distributed crawler: a URL server handing lists of URLs to several crawler processes, each keeping hundreds of connections open at once, with pages compressed and stored in a repository for indexing. It also noted the operational side, such as handling site owners' complaints and the endless variety of broken servers and pages on the real web."],
    'lesson': 'Crawling at web scale is as much about politeness and robustness to a messy web as about throughput.',
    'src': [['The Anatomy of a Large-Scale Hypertextual Web Search Engine', 'http://infolab.stanford.edu/~backrub/google.html']]}},
  {'case': {'who': 'IETF', 'when': '2022', 'title': 'robots.txt becomes a standard: RFC 9309',
    'body': ["The Robots Exclusion Protocol had been an informal convention since 1994. RFC 9309 standardised how crawlers must fetch, parse and cache robots.txt, how allow and disallow rules match, and what to do when the file is unreachable. Responsible crawlers check it before fetching from a host and honour it."],
    'lesson': 'Politeness is part of the specification. Build robots.txt handling and per-host rate limits into the frontier from the start.',
    'src': [['RFC 9309: Robots Exclusion Protocol', 'https://www.rfc-editor.org/rfc/rfc9309.html']]}},
  {'part': 'apply'},
  {'code': "// URL normalisation for dedup\nfunction normalize(raw) {\n  const u = new URL(raw);\n  u.hash = '';\n  u.hostname = u.hostname.toLowerCase();\n  if ((u.protocol === 'https:' && u.port === '443') || (u.protocol === 'http:' && u.port === '80')) u.port = '';\n  [...u.searchParams.keys()].filter(k => /^utm_|^fbclid$|^gclid$/.test(k)).forEach(k => u.searchParams.delete(k));\n  u.searchParams.sort();\n  if (u.pathname !== '/' && u.pathname.endsWith('/')) u.pathname = u.pathname.slice(0, -1);\n  return u.toString();\n}\nconsole.log(normalize('HTTPS://Example.com:443/news/?utm_source=x&b=2&a=1#top')); // https://example.com/news?a=1&b=2\n\n// Politeness: one back queue per host with a next-allowed time\nconst hosts = new Map();\nfunction nextFetch(now) {\n  for (const [host, q] of hosts) if (q.urls.length && q.nextAt <= now) { q.nextAt = now + q.delayMs; return q.urls.shift(); }\n  return null;\n}\nhosts.set('example.com', { urls: ['https://example.com/a', 'https://example.com/b'], nextAt: 0, delayMs: 1000 });\nconsole.log(nextFetch(0), nextFetch(10), nextFetch(1000)); // a, null (too soon), b", 'lang': 'js', 'cap': 'Two building blocks of a crawler'},
  {'check': ['Normalise every URL before checking whether it was seen.', 'Keep a per-host queue with a politeness delay and honour robots.txt.', 'Use a Bloom filter (or similar) for the seen-URL set at scale.', 'Detect duplicate content by hash or SimHash.', 'Cap depth, URL length and pages per host to avoid traps.', 'Schedule recrawls by observed change rate and use conditional requests.']},
]

L4 = [
  {'part': 'read'},
  "Counting looks trivial until a single counter receives 100,000 increments per second, or someone asks for 'the top 10 out of a billion items over the last hour'. Both problems are solved by the same move: stop updating one shared thing synchronously; aggregate in pieces and combine.",
  {'h': 'Sharded counters'},
  "Split one hot counter into N sub-counters (`likes:post9:0` to `likes:post9:15`). Each increment picks a random shard, so writes spread over N keys (and possibly N machines). Reading sums the shards, which is cheap, or a background job keeps a cached total. Alternatively, batch: each app server accumulates increments in memory for a second and flushes one `INCRBY` with the total.",
  {'h': 'Top-K over a window'},
  "Exact top-K over a stream needs a count for every item seen, which may be billions. Instead, a Count-Min Sketch estimates each item's count in fixed memory, and a min-heap of size K keeps the current leaders. Per time bucket (say each minute) you keep one sketch; the hourly top-K merges the last 60. For exact numbers, the same events also flow to batch storage for a nightly recount.",
  {'part': 'real'},
  {'case': {'who': 'Reddit', 'when': '2017', 'title': 'Counting post views with HyperLogLog',
    'body': ["Reddit wanted to show how many unique users had viewed each post, in near real time. Storing every viewer ID per post would have used a lot of memory for popular posts. View events flow through Kafka to a consumer that applies anti-spam rules, then to a counting service that keeps a HyperLogLog per post in Redis (about 12 KB at most) and periodically persists counts to Cassandra."],
    'lesson': 'For unique counts per item, HyperLogLog trades a small error for a huge memory saving, and a stream pipeline keeps it fresh.',
    'src': [['Counting is Hard: Probabilistic Algorithms for View Counting at Reddit (InfoQ talk)', 'https://www.infoq.com/presentations/algorithms-counting-reddit']]}},
  {'case': {'who': 'YouTube', 'when': '2014', 'title': '"Gangnam Style" outgrew a 32-bit view counter',
    'body': ["YouTube's view counter used a 32-bit signed integer, which tops out at 2,147,483,647. When Psy's 'Gangnam Style' approached that number, YouTube upgraded the counter to a 64-bit integer, joking that they had never imagined a video would be watched that many times."],
    'lesson': 'Size counters for the success you do not expect. A 64-bit integer costs four more bytes.',
    'src': [['Gangnam Style music video ‘broke’ YouTube view limit (BBC News)', 'https://www.bbc.com/news/world-asia-30288542']]}},
  {'part': 'apply'},
  {'code': "// Count-Min Sketch + top-K heap: approximate heavy hitters in fixed memory\nclass CMS {\n  constructor(w = 2048, d = 4) { this.w = w; this.d = d; this.t = Array.from({ length: d }, () => new Uint32Array(w)); }\n  idx(x, i) { let h = 2166136261 ^ (i * 16777619); for (const c of x) h = Math.imul(h ^ c.charCodeAt(0), 16777619); return (h >>> 0) % this.w; }\n  add(x) { for (let i = 0; i < this.d; i++) this.t[i][this.idx(x, i)]++; }\n  count(x) { let m = Infinity; for (let i = 0; i < this.d; i++) m = Math.min(m, this.t[i][this.idx(x, i)]); return m; }\n}\nconst cms = new CMS(), K = 3, top = new Map();\nconst stream = [];\nfor (let i = 0; i < 50000; i++) stream.push('#tag' + Math.floor(Math.pow(Math.random(), 4) * 5000)); // skewed hashtags\nfor (const tag of stream) {\n  cms.add(tag);\n  top.set(tag, cms.count(tag));\n  if (top.size > K * 10) { const sorted = [...top].sort((a, b) => b[1] - a[1]).slice(0, K * 5); top.clear(); sorted.forEach(([k, v]) => top.set(k, v)); }\n}\nconst exact = stream.reduce((m, t) => m.set(t, (m.get(t) || 0) + 1), new Map());\nconsole.log('sketch top 3:', [...top].sort((a, b) => b[1] - a[1]).slice(0, K));\nconsole.log('exact  top 3:', [...exact].sort((a, b) => b[1] - a[1]).slice(0, K));", 'lang': 'js', 'cap': 'Run it: the sketch finds the same leaders with a fraction of the memory'},
  {'code': "// Sharded counter in Redis: spread writes, sum on read\nconst SHARDS = 16;\nconst like = postId => redis.incr(`likes:${postId}:${Math.floor(Math.random() * SHARDS)}`);\nasync function likes(postId) {\n  const vals = await redis.mGet(Array.from({ length: SHARDS }, (_, i) => `likes:${postId}:${i}`));\n  return vals.reduce((a, v) => a + Number(v || 0), 0);\n}", 'lang': 'js', 'cap': 'Removing a hot key'},
  {'check': ['Find counters that receive many concurrent writes and shard or batch them.', 'Use 64-bit counters.', 'Decide which counts must be exact (billing) and which can be approximate (views).', 'Use HyperLogLog for unique counts and Count-Min Sketch for heavy hitters.', 'Aggregate per time bucket, then merge buckets for windows.', 'Keep raw events so exact numbers can be recomputed in batch.']},
]

LESSONS = [L0, L1, L2, L3, L4]
